from fastapi import FastAPI, Response, Depends
from fastapi.testclient import TestClient
from typing import Annotated

def modify_response():
    return Response(content="modified", media_type="text/plain")

app = FastAPI()

@app.get("/test1")
def endpoint1(response: Annotated[Response, Depends(modify_response)]):
    return {"message": "test1"}

@app.get("/test2")
def endpoint2(response: Response = Depends(modify_response)):
    return {"message": "test2"}

@app.get("/test3")
def endpoint3(response: Response):
    return {"message": "test3"}

client = TestClient(app)

def test_response_dependency():
    # Test 1: Annotated[Response, Depends(...)]
    # Note: The endpoint returns {"message": "test1"}, but the dependency modify_response returns a Response object.
    # In FastAPI, if a dependency returns a Response, it's not automatically used as the response of the endpoint
    # unless the endpoint itself returns it or it's a middleware.
    # However, the issue is about the ASSERTION ERROR during app startup/route definition.
    # So just calling the endpoint is enough to verify that it doesn't crash during dependency resolution.

    # Actually, the assertion error happens when the app is created and routes are analyzed.
    # So just creating the app and calling the endpoints should be enough.

    res1 = client.get("/test1")
    assert res1.status_code == 200

    res2 = client.get("/test2")
    assert res2.status_code == 200

    res3 = client.get("/test3")
    assert res3.status_code == 200

if __name__ == "__main__":
    test_response_dependency()
    print("All tests passed!")

